xql_query:
// ============================================================
// Rule: WIN_PowerShell Backup & Log Tampering
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_PowerShell Backup & Log Tampering.
// Severity: SEV_040_HIGH
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0040 - Impact
// Technique: T1490 - Inhibit System Recovery
// Tactic: TA0005 - Defense Evasion
// Technique: T1070.001 - Indicator Removal on Host: Clear Windows Event Logs

// Fonte de dados: eventos do Cortex XDR
dataset = xdr_data  

// Seleção dos campos relevantes para análise de execução de processos
| fields _time,                          // Data e hora do evento
         agent_hostname,                 // Host de origem
         actor_effective_username,       // Usuário que executou o processo
         actor_process_image_name,       // Nome do processo pai (neste caso, powershell.exe)
         actor_process_command_line,     // Linha de comando do processo pai
         action_process_image_name,      // Nome do processo disparado pelo pai
         action_process_image_command_line, // Linha de comando do processo filho
         event_type,                     // Tipo de evento (PROCESS)
         actor_process_os_pid            // PID do processo pai

// Filtro para manter apenas eventos de criação de processo (PROCESS)
| filter event_type = ENUM.PROCESS  

// Filtro para identificar execução do PowerShell (processo pai)
| filter lowercase(actor_process_image_name) = "powershell.exe"  

// Filtro para detectar processos críticos disparados pelo PowerShell
// - wevutil.exe → manipulação de logs de eventos
// - wbadmin.exe → gerenciamento de backup
// - wmic.exe → consultas WMI
// - bcedit.exe → configuração de boot
// - vssadmin.exe → gerenciamento de shadow copies
| filter lowercase(action_process_image_name) in ("wevutil.exe",
                                                  "wbadmin.exe",
                                                  "wmic.exe",
                                                  "bcedit.exe",
                                                  "vssadmin.exe")  

// Filtro para restringir ao host CORTEX (ponto específico de investigação)
| filter agent_hostname = "CORTEX"  

// Filtro para identificar linhas de comando que indicam:
// - Desativação de recuperação de boot
// - Exclusão de shadow copies e backups
// - Limpeza de logs do sistema e de segurança
| filter lowercase(action_process_image_command_line) ~= "/set {default} recoveryenabled no|/set {default} bootstatuspolicy ignoreallfailures|delete shadows /all /quiet|shadowcopy delete /noninteractive|stop job -quiet|disable backup -quiet|delete backup -keepversions:0 -quiet|delete systembackup -keepversions:0 -quiet|delete catalog -quiet|cl application|cl system|security|cl setup" 

// Agregação (comp) para correlacionar a atividade
// - Agrupa por host, processo pai e PID
// - Lista todos os comandos (CLIs) e processos distintos disparados
// - Conta quantidade de comandos distintos (dc_cli)
// - Conta quantidade de processos distintos (dc_process_name)
| comp values(action_process_image_command_line) as CLIs,
       values(action_process_image_name) as process_name,
       count_distinct(action_process_image_command_line) as dc_cli,
       count_distinct(action_process_image_name) as dc_process_name
  by agent_hostname, actor_process_image_name, actor_process_command_line, actor_process_os_pid  

// Mantém apenas casos onde houve uso de ≥3 comandos e ≥3 processos distintos
// → sinal forte de atividade maliciosa coordenada
| filter dc_cli >= 3 and dc_process_name >= 3
